INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 6, 'theory', 'Quiz: logic gates');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 6, 0, 'How many rows are in the truth table of a circuit with four inputs?', '["4", "8", "16", "32"]', 2, 'Each input doubles the number of combinations: 2 · 2 · 2 · 2 = 16. That is why large circuits are described with formulas rather than tables.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 6, 1, 'A NAND gate receives A = 1 and B = 1. What is on the output?', '["0", "1", "Depends on the supply", "An undefined value"]', 0, 'AND gives 1, and NOT inverts it — the result is 0. NAND outputs one for every input combination except “both ones”.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 6, 2, 'How do you get an inverter from a single NAND gate?', '["Leave one input unconnected", "Feed a constant one to one input and remove the other", "Put two gates in parallel", "Connect both inputs together"]', 3, 'When both inputs equal A, the output is not (A · A) = not A. An input must not be left “in the air”: its value is undefined.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 6, 3, 'In the circuit Y = A · E, the signal E is zero. What is on the output?', '["A copy of A", "The inverse of A", "Always 1", "Always 0"]', 3, 'A zero on one input of AND shuts the gate: the output freezes at zero, whatever arrives on A. This is how the “enable” (tap) works.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 6, 4, 'How do you build a circuit from a truth table using “sum of products”?', '["For each row with a one, write the product of the inputs (zero ones negated) and add them", "For the rows where the output is zero, write the sums of the inputs and multiply them", "Connect all inputs to a single OR gate", "Try gates until the table matches"]', 0, 'Each product “catches” exactly one row of the table. A sum of such products gives one in the needed rows and zero in all the others — the method works for any table.');
